public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the start and end coordinates are within the bounds of the maze
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Create a boolean array to keep track of visited nodes
    boolean[][] visited = new boolean[n][n];
    visited[start[0]][start[1]] = true;

    // Create a queue to perform BFS
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);

    // Perform BFS
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        // Check if the current node is the end node
        if (x == end[0] && y == end[1]) {
            return "can be travelled";
        }

        // Explore all four possible directions
        int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        for (int[] dir : directions) {
            int newX = x + dir[0];
            int newY = y + dir[1];

            // Check if the new coordinates are within the bounds of the maze and not visited
            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
                visited[newX][newY] = true;
                queue.offer(new int[]{newX, newY});
            }
        }
    }

    // If the queue is empty, it means the end node was not reached
    return "cannot be travelled";
}
