public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null || word1.isEmpty() || word2.isEmpty()) {
        throw new IllegalArgumentException("Both words must be non-null and non-empty.");
    }

    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }

    int totalLength = word1.length() + word2.length();
    if (totalLength == 0) {
        throw new IllegalArgumentException("Total length of words must be non-zero.");
    }

    int gcd = gcd(commonLetters, totalLength);
    return "appx(" + word1 + ", " + word2 + ") = " + commonLetters / gcd + "/" + totalLength / gcd;
}

private static int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}
