private static int countDigitOneHelper(int num) {
    if (num == 0) {
        return 0;
    }
    int count = 0;
    int power = 1;
    while (num >= power) {
        int digit = num / power % 10;
        if (digit == 1) {
            count += (num - power + 1) * power;
        } else if (digit > 1) {
            count += power;
        }
        power *= 10;
    }
    return count;
}
